    console.log("typeof medicine =", typeof medicine);
    if (!medicine) {
      alert("Medicine is undefined");
      return;
    }
    console.log("Selected Medicine:", medicine);
    item.medicineId = medicine.id;
    item.medicineName = medicine.medicineName;
    item.suggestions = [];
